function bookingDurationHours(minutes){const h=Number(minutes)/60;return String(Math.round(h*100)/100)+' '+(h===1?'hour':'hours')}
/* Private planner demonstration. Real isolation requires server-side permissions. */
const normaliseBeforePlanner=normalise;
normalise=function(){normaliseBeforePlanner();state.subbies??=[];state.privateBookings??=[];if(!state.privatePlannerVersion){state.subbies.push({id:'sub-demo-plumbing',name:'Demo Plumbing Partner',contact:'Alex · example contact',phone:'082 555 0120',email:'plumbing@example.com',trade:'Plumbing',area:'Meyerton / Vaal'},{id:'sub-demo-repairs',name:'Demo Repairs Partner',contact:'Sam · example contact',phone:'083 555 0130',email:'repairs@example.com',trade:'General maintenance',area:'Gauteng'});const job=state.jobs.find(j=>j.ref==='DEMO-VISIT');if(job?.schedule)state.privateBookings.push({id:id('booking'),job:job.id,subbie:'sub-demo-plumbing',when:job.schedule.when,duration:60,price:650,instructions:'Example only: investigate bathroom fitting. Call the tenant before arrival.',internalNote:'Subbie price and assignment stay in the private planner.',status:'Accepted',acceptedAt:now(),createdAt:now(),log:[{at:now(),text:'Example assignment accepted by phone.'}]});state.privatePlannerVersion=1}};
let plannerTab='calendar',plannerFilter='All bookings';
const renderBeforePlanner=render;render=function(){renderBeforePlanner();if(role==='sevlink')$('#nav').insertAdjacentHTML('beforeend',`<button data-view="privateplanner" class="${view==='privateplanner'?'active':''}">▣ &nbsp; Private subbie planner</button>`);if(view==='privateplanner')renderPrivatePlanner()};
function bookingJob(b){return state.jobs.find(j=>j.id===b.job)}function bookingSubbie(b){return state.subbies.find(s=>s.id===b.subbie)}
function plannerAllowed(){if(role==='sevlink')return true;app.innerHTML=heading('Sevlink staff access required.','This planner is not part of the agency or tenant workspace.');return false}
function renderPrivatePlanner(){if(!plannerAllowed())return;const bookings=state.privateBookings.filter(b=>plannerFilter==='All bookings'||b.status===plannerFilter).sort((a,b)=>a.when.localeCompare(b.when));app.innerHTML=heading('Your private subbie planner.','Who is attending, where, when — and at what internal cost.','<button class="primary" onclick="bookingForm()">＋ Assign subbie to job</button>')+`<div class="banner"><b>SEVLINK STAFF ONLY · DEMO</b><br>Subbie contacts, prices, instructions and acceptance records are excluded from agency and tenant views. Real sign-in and server-side access control are still required before launch.</div><div class="stats" style="margin-top:20px">${[['Subbies',state.subbies.length],['Awaiting acceptance',state.privateBookings.filter(b=>b.status==='Awaiting response').length],['Accepted bookings',state.privateBookings.filter(b=>b.status==='Accepted').length],['Needs rescheduling',state.privateBookings.filter(b=>b.status==='Declined').length]].map(([l,n])=>`<div class="stat"><label>${l}</label><strong>${n}</strong><small>Internal records</small></div>`).join('')}</div><div class="tabs"><button onclick="plannerTab='bookings';renderPrivatePlanner()" class="${plannerTab==='bookings'?'selected':''}">Assignments & dates</button><button onclick="plannerTab='subbies';renderPrivatePlanner()" class="${plannerTab==='subbies'?'selected':''}">Subbie directory</button></div>${plannerTab==='subbies'?directoryMarkup():`<div class="panel"><div class="panelhead"><div><h2>Attendance planner</h2><p>Tentative assignments do not change the client’s confirmed appointment.</p></div><select id="plannerFilter" aria-label="Filter private assignments">${['All bookings','Awaiting response','Accepted','Declined','Attended','Cancelled'].map(s=>`<option ${s===plannerFilter?'selected':''}>${s}</option>`).join('')}</select></div>${bookings.length?`<div class="tablewrap"><table><thead><tr><th>DATE / TIME</th><th>SUBBIE</th><th>PROPERTY / JOB</th><th>PRIVATE COST</th><th>ACCEPTANCE</th><th></th></tr></thead><tbody>${bookings.map(b=>{const j=bookingJob(b),s=bookingSubbie(b);return `<tr onclick="privateBookingDetail('${b.id}')" tabindex="0" onkeydown="if(event.key==='Enter')privateBookingDetail('${b.id}')"><td><strong>${b.when.slice(0,10)}</strong>${b.when.slice(11)} SAST<br><small>${bookingDurationHours(b.duration)}</small></td><td><strong>${esc(s?.name)}</strong><small>${esc(s?.trade)}</small></td><td><strong>${esc(property(j?.property)?.name)}</strong><small>${esc(j?.ref)} · ${esc(j?.title)}</small></td><td>${money(b.price)}</td><td>${badge(b.status)}</td><td>↗</td></tr>`}).join('')}</tbody></table></div>`:'<p>No assignments match this filter.</p>'}</div><div class="notice">Record acceptance after the subbie replies by phone, email or WhatsApp. Nothing is sent automatically. Confirm the client appointment only after availability and access have been agreed.</div>`}`;if($('#plannerFilter'))$('#plannerFilter').onchange=e=>{plannerFilter=e.target.value;renderPrivatePlanner()}}
function directoryMarkup(){return `<div class="panel"><div class="panelhead"><h2>Your maintenance partners</h2><button class="secondary" onclick="subbieForm()">＋ Add subbie</button></div><div class="cards">${state.subbies.map(s=>`<div class="card"><span class="eyebrow">${esc(s.trade)}</span><h2>${esc(s.name)}</h2><p>${esc(s.contact)}<br>${esc(s.phone)}<br>${esc(s.email)}<br>${esc(s.area)}</p><button class="secondary" onclick="subbieForm('${s.id}')">Edit partner</button></div>`).join('')||'<p>No subbies added yet.</p>'}</div></div>`}
function subbieForm(sid){if(role!=='sevlink')return;const s=state.subbies.find(s=>s.id===sid)||{};openForm(sid?'Edit subbie.':'Add a subbie.',field('Business / subbie name','name',s.name)+field('Contact person','contact',s.contact)+field('Phone / WhatsApp','phone',s.phone,'tel')+field('Email','email',s.email,'email')+field('Trade','trade',s.trade)+field('Service area','area',s.area),'Save private contact',async d=>{if(await commit(()=>{if(s.id)Object.assign(s,Object.fromEntries(d));else state.subbies.push({id:id('sub'),...Object.fromEntries(d)})})){modal.close();render();toast('Private subbie contact saved.')}})}
function overlappingBooking(subbie,when,duration,ignore){const start=Date.parse(when+'+02:00'),end=start+duration*60000;return state.privateBookings.find(b=>b.id!==ignore&&b.subbie===subbie&&!['Declined','Cancelled','Attended'].includes(b.status)&&start<Date.parse(b.when+'+02:00')+b.duration*60000&&end>Date.parse(b.when+'+02:00'))}
function bookingForm(bid='',jobid=''){if(role!=='sevlink')return;const b=state.privateBookings.find(b=>b.id===bid)||{},jobs=visibleJobs().filter(j=>!['Completed','Cancelled'].includes(j.status));if(!state.subbies.length){toast('Add a subbie to your directory first.');return}if(!jobs.length){toast('There are no open jobs to assign.');return}const suggested=state.jobs.find(j=>j.id===(b.job||jobid));openForm(bid?'Edit private assignment.':'Assign a subbie.',`<label>Property / job</label><select name="job">${jobs.map(j=>`<option value="${j.id}" ${(b.job||jobid)===j.id?'selected':''}>${esc(property(j.property)?.name)} · ${j.ref} · ${esc(j.title)}</option>`).join('')}</select><label>Subbie</label><select name="subbie">${state.subbies.map(s=>`<option value="${s.id}" ${b.subbie===s.id?'selected':''}>${esc(s.name)} — ${esc(s.trade)}</option>`).join('')}</select><label>Tentative attendance date & time (SAST)</label><input name="when" type="datetime-local" value="${esc(b.when||suggested?.schedule?.when||'')}" required><div class="row"><div><label>Estimated duration (hours)</label><input name="hours" type="number" min="0.25" max="12" step="0.25" required value="${(b.duration||60)/60}"></div><div><label>Subbie price (ZAR, private)</label><input name="price" type="number" min="0" max="10000000" step="0.01" required value="${b.price??''}"></div></div><label>Instructions for the subbie</label><textarea name="instructions" rows="3" maxlength="2000" required>${esc(b.instructions||'')}</textarea><label>Private Sevlink notes (not included in dispatch preview)</label><textarea name="internalNote" rows="3" maxlength="2000">${esc(b.internalNote||'')}</textarea><div class="notice">Saving this assignment does not notify the tenant or confirm a client appointment. Date, job or subbie changes reset acceptance.</div>`,'Save private assignment',async d=>{const record={...Object.fromEntries(d),duration:Number(d.get('hours'))*60,price:Number(d.get('price'))};if(await savePrivateBooking(bid,record)){modal.close();navigate('privateplanner');toast('Private assignment saved.')}})}
async function savePrivateBooking(bid,record){if(role!=='sevlink'||!state.subbies.some(s=>s.id===record.subbie)||!visibleJobs().some(j=>j.id===record.job&&j.status!=='Completed'))return false;const ms=Date.parse(record.when+'+02:00');if(!Number.isFinite(ms)||ms<=Date.now()||!Number.isFinite(record.duration)||record.duration<15||record.duration>720||!Number.isFinite(record.price)||record.price<0){toast('Choose a future date, valid duration and price.');return false}if(overlappingBooking(record.subbie,record.when,record.duration,bid)){toast('This subbie already has an overlapping assignment. Choose another time or person.');return false}const existing=state.privateBookings.find(b=>b.id===bid);if(state.privateBookings.some(b=>b.id!==bid&&b.job===record.job&&!['Cancelled','Declined','Attended'].includes(b.status))){toast('This job already has an active subbie assignment. Edit it instead.');return false}return commit(()=>{if(existing){const reset=existing.when!==record.when||existing.subbie!==record.subbie||existing.job!==record.job||existing.duration!==record.duration;Object.assign(existing,record);if(reset){existing.status='Awaiting response';existing.acceptedAt=null}existing.log.push({at:now(),text:'Private assignment edited'+(reset?'; acceptance reset.':'.')})}else state.privateBookings.push({id:id('booking'),...record,status:'Awaiting response',acceptedAt:null,createdAt:now(),log:[{at:now(),text:'Assignment created; awaiting subbie reply.'}]})})}
function privateBookingDetail(bid){if(role!=='sevlink')return;const b=state.privateBookings.find(b=>b.id===bid);if(!b)return;const j=bookingJob(b),s=bookingSubbie(b),p=property(j.property),t=state.tenants.find(t=>t.id===j.tenant);modal.innerHTML=`<button class="close" onclick="modal.close()">×</button><span class="eyebrow">SEVLINK PRIVATE ASSIGNMENT</span><h1>${esc(s.name)}</h1>${badge(b.status)}<p><b>${esc(p?.name)}</b><br>${esc(p?.address)}<br>${j.ref} · ${esc(j.title)}<br>${attendanceTime(b.when)} · ${bookingDurationHours(b.duration)}</p><div class="notice"><b>Private subbie cost:</b> ${money(b.price)}<br><b>Contact:</b> ${esc(s.contact)} · ${esc(s.phone)}<br>${esc(s.email)}</div><h2>Access & property contact</h2><p>${esc(t?.name||'Arrange access through Sevlink')} ${esc(t?.phone||'')}<br>${esc(j.access?.note||'No shared access instructions recorded yet.')}</p><h2>Subbie instructions</h2><p style="white-space:pre-wrap">${esc(b.instructions)}</p><h2>Private Sevlink notes</h2><p style="white-space:pre-wrap">${esc(b.internalNote||'No private notes.')}</p><div class="notice"><b>Client calendar:</b> ${j.schedule?.status==='Confirmed'?'Sevlink attending · '+attendanceTime(j.schedule.when):'No confirmed attendance published yet'}${j.schedule?.status==='Confirmed'&&j.schedule.when!==b.when?'<br>⚠ Private assignment differs from the client appointment. Agree and confirm any change.':''}</div><div class="actions">${!['Cancelled','Attended'].includes(b.status)?`<button class="primary" onclick="acceptanceForm('${bid}')">Record subbie reply</button><button class="secondary" onclick="bookingForm('${bid}')">Edit assignment</button>`:''}<button class="secondary" onclick="dispatchPreview('${bid}')">Preview job brief</button>${b.status==='Accepted'?`<button class="primary" onclick="confirmBookingForm('${bid}')">Confirm client appointment</button>`:''}${['Accepted','Attended'].includes(b.status)?`<button class="secondary" onclick="subbieReportForm('${bid}')">Record subbie report</button>`:''}</div>${b.report?`<div class="card" style="margin-top:20px"><span class="eyebrow">PRIVATE SUBBIE REPORT</span><p style="white-space:pre-wrap">${esc(b.report.text)}</p>${b.report.photo?`<img src="${b.report.photo.data}" alt="Private subbie report photo" style="max-width:100%;max-height:220px">`:''}<p>${date(b.report.at)}</p><button class="secondary" onclick="publishUpdateForm('${bid}')">Prepare client-facing update</button></div>`:''}<h2 style="margin-top:24px">Internal assignment log</h2>${b.log.map(l=>`<div class="activity">${esc(l.text)}<small>${date(l.at)}</small></div>`).join('')}<p class="muted">No message is sent automatically. Agency and tenant views do not display this assignment.</p>`;if(!modal.open)modal.showModal()}
function acceptanceForm(bid){if(role!=='sevlink')return;const b=state.privateBookings.find(b=>b.id===bid);if(!b)return;openForm('Record the subbie’s reply.',`<label>Response</label><select name="status"><option value="Accepted">Accepted the date & time</option><option value="Declined">Declined — needs another person / time</option><option value="Awaiting response">Still awaiting response</option><option value="Cancelled">Cancel this assignment</option></select><label>Reply received via</label><select name="via"><option>WhatsApp</option><option>Email</option><option>Phone call</option></select><label>Response / internal notes</label><textarea name="note" rows="3" required maxlength="1500"></textarea><div class="notice">This manually records a reply you have received. It does not contact the subbie.</div>`,'Save reply',async d=>{if(await saveSubbieReply(bid,d.get('status'),d.get('via'),d.get('note'))){render();privateBookingDetail(bid);toast('Subbie response recorded privately.')}})}
async function saveSubbieReply(bid,status,via,note){const b=state.privateBookings.find(b=>b.id===bid);if(!b||role!=='sevlink'||!['Accepted','Declined','Awaiting response','Cancelled'].includes(status)||['Cancelled','Attended'].includes(b.status))return false;if(status==='Accepted'&&overlappingBooking(b.subbie,b.when,b.duration,bid)){toast('An overlapping booking must be resolved first.');return false}return commit(()=>{b.status=status;b.acceptedAt=status==='Accepted'?now():null;b.log.push({at:now(),text:status+' via '+via+': '+note})})}
function dispatchText(b){const j=bookingJob(b),p=property(j.property),t=state.tenants.find(t=>t.id===j.tenant);return `SEVLINK JOB BRIEF\nReference: ${j.ref}\nProperty: ${p?.name}\nAddress: ${p?.address}\nAttendance: ${attendanceTime(b.when)}\nEstimated duration: ${bookingDurationHours(b.duration)}\nIssue: ${j.title}\nInstructions: ${b.instructions}\nAccess contact: ${t?.name||'Arrange through Sevlink'} ${t?.phone||''}\n\nPlease confirm acceptance of this appointment to Sevlink. Send findings, photos and your work report to Sevlink using this job reference. Do not agree extra charges directly with the client; obtain Sevlink authorisation.`}
function dispatchPreview(bid){if(role!=='sevlink')return;const b=state.privateBookings.find(b=>b.id===bid);if(!b)return;const s=bookingSubbie(b);modal.innerHTML=`<button class="close" onclick="modal.close()">×</button><span class="eyebrow">PRIVATE DISPATCH PREVIEW · NOT SENT</span><h1>Job brief for ${esc(s.name)}</h1><p>WhatsApp: ${esc(s.phone)}<br>Email: ${esc(s.email)}</p><textarea readonly rows="16" aria-label="Job brief to copy" style="width:100%">${esc(dispatchText(b))}</textarea><div class="notice">Copy this brief into your email or WhatsApp. It excludes the client price and private Sevlink notes. Nothing has been sent.</div><button class="secondary" onclick="privateBookingDetail('${bid}')">Back to assignment</button>`;if(!modal.open)modal.showModal()}
function activeJobBooking(jid){return state.privateBookings.find(b=>b.job===jid&&!['Cancelled','Declined','Attended'].includes(b.status))}
function acceptedForDate(jid,when){const b=activeJobBooking(jid);return !b||(b.status==='Accepted'&&b.when===when)}
function confirmBookingForm(bid){if(role!=='sevlink')return;const b=state.privateBookings.find(b=>b.id===bid);if(!b||b.status!=='Accepted')return;const j=bookingJob(b);if(!approved(j)){toast('Client cost or call-out authorisation is required before confirming attendance.');return}openForm('Confirm the client appointment.',`<p>${esc(property(j.property)?.name)}<br><b>${attendanceTime(b.when)}</b></p><label style="display:flex;gap:10px;align-items:center"><input name="agreed" type="checkbox" required style="width:auto">The tenant / agency has agreed to this date and time.</label><label>Client-facing access / appointment note</label><textarea name="note" rows="3" maxlength="1000" placeholder="Only write information the tenant and agency should see."></textarea><div class="notice">The client sees a Sevlink appointment. The subbie identity, internal price and private notes are not published.</div>`,'Confirm Sevlink appointment',async d=>{if(await saveSchedule(j.id,b.when,d.get('note'),true,!!d.get('agreed'))){render();privateBookingDetail(bid);toast('Sevlink appointment confirmed for the client.')}})}
const saveScheduleBeforePlanner=saveSchedule;saveSchedule=async function(jid,when,note,agreed=false,byPhone=false){if(role==='sevlink'&&agreed&&!acceptedForDate(jid,when)){toast('The assigned subbie must accept this exact date and time before the client appointment is confirmed.');return false}return saveScheduleBeforePlanner(jid,when,note,agreed,byPhone)};
const approveDateBeforePlanner=approveDate;approveDate=async function(jid){const j=getJob(jid);if(role==='sevlink'&&j?.schedule&&!acceptedForDate(jid,j.schedule.when)){toast('Confirm the assigned subbie’s acceptance of this date before approving the client appointment.');return}return approveDateBeforePlanner(jid)};
function subbieReportForm(bid){if(role!=='sevlink')return;const b=state.privateBookings.find(b=>b.id===bid);if(!b||!['Accepted','Attended'].includes(b.status))return;openForm('Record a private subbie report.',`<label>Findings / work report received</label><textarea name="text" rows="5" required maxlength="3000">${esc(b.report?.text||'')}</textarea><label>Received via</label><select name="via"><option>WhatsApp</option><option>Email</option><option>Phone call</option></select><label>Photo received (optional, up to 5 MB)</label><input type="file" name="photo" accept="image/jpeg,image/png,image/webp"><div class="notice">This report remains private. Review it before preparing any client-facing update.</div>`,'Save private report',async d=>{let photo;try{photo=await fileData(d.get('photo'),imageTypes)}catch(e){toast(e.message);return}if(await commit(()=>{b.report={text:d.get('text'),via:d.get('via'),photo:photo||b.report?.photo||null,at:now()};b.status='Attended';b.log.push({at:now(),text:'Subbie report recorded via '+d.get('via')+'. Not published to the client.'})})){render();privateBookingDetail(bid);toast('Subbie report saved privately.')}})}
function publishUpdateForm(bid){if(role!=='sevlink')return;const b=state.privateBookings.find(b=>b.id===bid);if(!b?.report)return;openForm('Prepare a Sevlink client update.',`<p>Review the private report, then write the update you want the client to receive.</p><label>Client-facing update</label><textarea name="text" required rows="5" maxlength="2000" placeholder="Write a clean summary of the findings or completed work. Private notes are not copied automatically."></textarea>${b.report.photo?'<label style="display:flex;gap:10px;align-items:center"><input name="photo" type="checkbox" style="width:auto">Publish the report photo too (check it is suitable for the client).</label>':''}<div class="notice">Only this written update and the selected photo are added to the client job. Subbie price, identity and private notes remain in the planner.</div>`,'Publish to client job',async d=>{if(await publishSubbieUpdate(bid,d.get('text'),!!d.get('photo'))){render();jobDetail(b.job);toast('Sevlink update added to the client job.')}})}
async function publishSubbieUpdate(bid,text,photo){const b=state.privateBookings.find(b=>b.id===bid);if(role!=='sevlink'||!b?.report||!text?.trim())return false;const j=bookingJob(b);return commit(()=>{j.comments.push({author:'Sevlink',text:text.trim(),visibility:'shared',at:now()});if(photo&&b.report.photo){const p={...b.report.photo,name:'Sevlink-job-update.'+(b.report.photo.type==='image/jpeg'?'jpg':b.report.photo.type==='image/png'?'png':'webp'),phase:'before',at:now()};j.photos.push(p);j.beforePhotos.push(p)}b.log.push({at:now(),text:'Reviewed Sevlink client update published.'})})}
const detailBeforePlanner=jobDetail;jobDetail=function(jid,section='comments'){detailBeforePlanner(jid,section);if(role!=='sevlink')return;const j=getJob(jid);if(!j)return;const b=activeJobBooking(jid)||[...state.privateBookings].reverse().find(b=>b.job===jid&&b.status==='Attended');$('#jobcontent').insertAdjacentHTML('beforeend',`<div class="private-assignment-box"><span class="eyebrow">SEVLINK PRIVATE · NOT SHOWN TO CLIENT</span><h2>Subbie assignment</h2>${b?`<p><b>${esc(bookingSubbie(b)?.name)}</b> · ${esc(b.status)}<br>${attendanceTime(b.when)}<br>Internal cost: ${money(b.price)}</p><button class="secondary" onclick="privateBookingDetail('${b.id}')">Open private assignment</button>${b.status==='Attended'&&j.status!=='Completed'?`<button class="secondary" onclick="bookingForm('', '${j.id}')">Assign return visit</button>`:''}`:j.status!=='Completed'?`<p>No subbie assigned yet.</p><button class="secondary" onclick="bookingForm('', '${j.id}')">Assign a subbie</button>`:'<p>No subbie assignment recorded.</p>'}</div>`)};

const conflictBeforePlanner=scheduleConflict;
scheduleConflict=function(j,when){const assigned=activeJobBooking(j.id);if(!assigned||assigned.status!=='Accepted')return conflictBeforePlanner(j,when);const start=Date.parse(when+'+02:00'),end=start+assigned.duration*60000;return state.jobs.find(other=>{if(other.id===j.id||other.status==='Completed'||other.schedule?.status!=='Confirmed')return false;const booking=activeJobBooking(other.id);const sameResource=booking?booking.subbie===assigned.subbie:other.team===j.team;return sameResource&&start<Date.parse(other.schedule.when+'+02:00')+(booking?.duration||other.duration||60)*60000&&end>Date.parse(other.schedule.when+'+02:00')})};
